INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('wirefrimes', 'WireFrimes', '/projects/WireFrimes.webp', '["UI/UX","HTML5","CSS3","JavaScript","Sass","Gulp","Netlify"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_webdevelopment-frontenddevelopment-wireframetowebsite-activity-7286881599680376832-zmt7?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/WireFrames-Sites', 'https://wireframe-training-luiz.netlify.app', 'Este projeto consiste em uma página principal interativa que permite acessar diferentes wireframes, com um menu dinâmico para facilitar a navegação. Ele foi desenvolvido para praticar a construção de interfaces baseadas em reframes e aplicar boas práticas de desenvolvimento web.', 'This project is an interactive main page that lets you access different wireframes, with a dynamic menu to ease navigation. It was built to practice creating wireframe-based interfaces and to apply good web development practices.', '12 de janeiro 2024', 'January 12, 2024', 2, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('api-cep', 'API-CEP', '/projects/API-CEP.webp', '["HTML5","CSS3","JavaScript","API","UI/UX"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_projeto-de-front-end-lan%C3%A7ado-buscar-cep-activity-7197338952368820224-wtLX?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/API_BuscarCep', 'https://buscarcepluiz.netlify.app', 'Desenvolvi uma ferramenta para busca de CEPs no Brasil, o site permite que os usuários encontrem informações detalhadas sobre endereços apenas inserindo o CEP.', 'I built a tool to look up Brazilian postal codes (CEP); the site lets users find detailed address information just by entering the CEP.', '20 de Maio 2024', 'May 20, 2024', 3, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('api-pokemon', 'API-Pokemon', '/projects/API-Pokemon.webp', '["HTML5","CSS3","JavaScript","API"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_projeto-de-front-end-pokemon-sobre-activity-7197338670616498178-FYUo?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/Pokemon', 'https://pokemonluiz.netlify.app', 'Este site foi desenvolvido para oferecer um guia completo de Pokémons, ideal para fãs que querem explorar e caçar Pokémons pelo mundo, integrando dados de uma API para exibir informações detalhadas sobre cada Pokémon.', 'This site was built to offer a complete Pokémon guide, ideal for fans who want to explore and hunt Pokémon around the world, integrating data from an API to display detailed information about each Pokémon.', '20 de Maio 2024', 'May 20, 2024', 4, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('barberweb', 'BarberWeb', '/projects/BarberWeb.webp', '["HTML5","CSS","Sass","JavaScript","UX/UI"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_desenvolvimentoweb-frontend-educaaexaeto-activity-7199779916848975872-c5vG?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/CabeleireiroPratic', 'https://cabeleireiroluiz.netlify.app', 'Este projeto foi desenvolvido com o objetivo de criar um site funcional e atraente para um salão de barbearia, oferecendo serviços de corte de cabelo e barba. Além de ser um projeto acadêmico integrador, que uniu estudantes do 4º e 2º período da faculdade, foi também uma oportunidade de praticar e aprimorar habilidades individuais em design e codificação, após a necessidade de reconstruir o projeto sem dados pessoais de terceiros, OBS: essas imagem foram criada com Inteligência Artificial.', 'This project aimed to create a functional and appealing website for a barbershop, offering haircut and beard services. Besides being an integrative academic project that brought together 4th- and 2nd-semester college students, it was also a chance to practice and improve individual design and coding skills, after the need to rebuild it without third parties\' personal data. NOTE: these images were created with Artificial Intelligence.', '14 de Outubro 2024', 'October 14, 2024', 5, 1);
INSERT INTO projects (slug, nome, imagem, tecnologias, link_linkedin, link_github, link_ver_projeto, descricao_pt, descricao_en, data_pt, data_en, ordem, publicado) VALUES ('blizzard', 'Blizzard', '/projects/Blizzard.webp', '["HTML5","CSS3","Sass","JavaScript"]', 'https://www.linkedin.com/posts/luiz-antonio-souza-5000a226b_projeto-de-front-end-blizzard-sobre-activity-7197338443922726912-bST3?utm_source=share&utm_medium=member_desktop', 'https://github.com/LuixzSouza/Blizzard', 'https://blizzardluiz.netlify.app', 'Este site foi desenvolvido para exibir uma série de jogos populares da Blizzard.', 'This site was built to showcase a series of popular Blizzard games.', '20 de Maio 2024', 'May 20, 2024', 6, 1);
